package com.example.helpdesk.config; import com.example.helpdesk.model.User; import com.example.helpdesk.model.Role; import com.example.helpdesk.repo.UserRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(UserRepository users,PasswordEncoder enc){return args->{if(users.count()==0){users.save(new User("employee",enc.encode("employee123"),"Demo Employee",Role.EMPLOYEE)); users.save(new User("technician",enc.encode("technician123"),"Demo Technician",Role.TECHNICIAN));}};} }
